query:
UPDATE orders 
SET ready_at = DATE_ADD(createdAt, INTERVAL FLOOR(TIMESTAMPDIFF(SECOND, createdAt, picked_up_at) * 0.65) SECOND)
WHERE ready_at IS NULL AND picked_up_at IS NOT NULL;

